// Validate x-arkos-secret header
const headers = $input.first().json.headers || {};
const expectedSecret = 'Y9D2LFdEVlzcqaLv7C2zn9v4V94RfP9CGuXW7FLC2iyOLSQLoOy-i9m-cdPcMS0Y';
const received = headers['x-arkos-secret'];
if (received !== expectedSecret) {
  return [{ json: { valid: false } }];
}
return [{ json: { valid: true } }];

// Prepare context from incoming message
const raw = $node['Agent Webhook'].json;
const body = raw.body || raw;

return [{ json: {
  user_id: body.user_id || '',
  from: body.from || '',
  name: body.name || 'Jona',
  message: body.message || '',
  message_type: body.message_type || 'text',
  phone_number_id: body.phone_number_id || '',
  wamid: body.wamid || ''
}}];

// Format final output from AI Agent
const agentOutput = $input.first().json;
const response = agentOutput.output || agentOutput.text || 'Perdón Jona, tuve un problema procesando tu mensaje. — ARKOS';

// Try to detect department from response content
let department = 'agenda';
const lower = response.toLowerCase();
if (lower.includes('gasto') || lower.includes('factura') || lower.includes('pago') || lower.includes('finanz')) {
  department = 'finanzas';
} else if (lower.includes('mail') || lower.includes('minuta') || lower.includes('documento') || lower.includes('decisión')) {
  department = 'documentos';
}

// Try to detect intent
let intent = 'general_response';
if (lower.includes('tarea') || lower.includes('recordatorio')) intent = 'task_management';
else if (lower.includes('reunión') || lower.includes('agenda') || lower.includes('calendario')) intent = 'calendar_management';
else if (lower.includes('memoria') || lower.includes('guardé') || lower.includes('anotado')) intent = 'memory_write';
else if (lower.includes('aprobación') || lower.includes('confirmar')) intent = 'approval_request';

return [{ json: {
  response: response,
  department: department,
  intent: intent
}}];
